#include <google/protobuf/util/field_mask_util.h>

FieldMask mask;
mask.add_paths("id");
mask.add_paths("reference");
mask.add_paths("lines.item");          // leave totals, notes, audits behind
FieldMaskUtil::TrimMessage(mask, &order);   // projection, in place
std::string wire; order.SerializeToString(&wire);

struct OrderView {
    std::uint64_t id;
    std::string_view reference;
    std::optional<std::string_view> coupon;
};

OrderView project(const Order& o) {
    return { o.id, o.reference, o.coupon.empty() ? std::nullopt
                                                 : std::optional{o.coupon} };
}

